        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    # Fast doubling method: O(log n)
    def _fib_doubling(k: int) -> tuple[int, int]:
        # Returns (F(k), F(k+1))
        if k == 0:
            return (0, 1)
        a, b = _fib_doubling(k >> 1)
        c = a * (2 * b - a)
        d = a * a + b * b
        if k & 1:
            return (d, c + d)
        else:
            return (c, d)

    return _fib_doubling(n)[0]
